\set ON_ERROR_STOP 0
DROP TABLE IF EXISTS G;
CREATE TABLE G (Id integer NOT NULL PRIMARY KEY, Loc geography NULL);
-- `sqldiff convert --to postgres` output, as written:
SELECT Id, ST_SRID(Loc), ST_AsText(Loc), upper(encode(float8send(ST_X(Loc::geometry)), 'hex')), upper(encode(float8send(ST_Y(Loc::geometry)), 'hex')), upper(encode(float8send(ST_Z(Loc::geometry)), 'hex')), upper(encode(float8send(ST_M(Loc::geometry)), 'hex')) FROM G ORDER BY Id;
-- Rows 16, 17, 18, 24 are left as bytea by the converter; PostGIS rejects each:
-- What PostGIS makes of longitude 180.5 given as a point (it moves it):
SELECT ST_AsText(ST_SetSRID(ST_MakePoint(180.5, 0), 4326)::geography);
